const leads = [
  { name: "Ali Hassan", leadScore: 95, leadTier: "Hot" },
  { name: "Sara Khan", leadScore: 55, leadTier: "Warm" },
  { name: "Omar Yusuf", leadScore: 25, leadTier: "Standard" },
  { name: "Fatima Noor", leadScore: 85, leadTier: "Hot" },
  { name: "Yusuf Al-Amin", leadScore: 60, leadTier: "Warm" }
];

// 1. FILTER — only Warm leads
const warmLeads = leads.filter(lead => lead.leadTier === "Warm");

// 2. SORT — ascending by score (lowest first)
const sortedAscending = [...leads].sort((a, b) => a.leadScore - b.leadScore);

// 3. REDUCE — total score of Warm leads only
const warmTotal = warmLeads.reduce((sum, lead) => sum + lead.leadScore, 0);

// 4. MAP — readable summary strings
const summaries = leads.map(lead => 
  `${lead.name} is ${lead.leadTier} tier with ${lead.leadScore} points`
);

return [{
  json: {
    warmLeads,
    sortedAscending,
    warmTotal,
    summaries
  }
}];
